window.__savePlan = (name) => savePlan(name);
window.__loadPlan = (name = null) => loadPlan(name);
// the design shelf, for the harness: rebuild it, and open one by name the
// way a double-click on its card would
window.__designUi = {
  render: () => renderDesignList(),
  open: (name) => {
    const bp = blueprints.find((b) => b.name === name);
    if (bp) openDesignWorld(bp);
    return !!bp;
  },
};
// the clipboard, for the harness: mark, copy, aim, paste, without keystrokes
window.__clip = {
  mark: (a, b) => { planner.a = a; planner.b = b; drawPlannerBox(); },
  copy: () => { copySelection(); return clipboard?.size ?? null; },
  paste: (at = null) => pasteClipboard(at),
  turn: () => { turnClipboard(); return clipboard?.size ?? null; },
};
window.__sysview = (dt = 1 / 60) => { updateSystemView(dt); return systemMarkers.length; };
window.__city = () => ({ grid: planet?.city ?? null, life: activeCityLife()?.counts ?? null });
window.__inv = () => inventory;
// The flock and the bed. Shearing and sleeping are both right-click gestures
// aimed at something, which a harness cannot express; these are the same two
// actions with the aiming taken out, so a check can prove a fleece comes off
// and a night goes past without driving a mouse.
// The shop, its shelves and its prices. Opening a counter needs a crosshair
// on a table three blocks away, which a harness cannot produce; this is the
// same window with the aiming taken out.
// The village purses, and what has come off their shelves. The one piece of
// state in this world besides the edit diff, so a check has to be able to read
// it directly rather than inferring it from a shop window.
// The chief. Its scoreboard, the brief it would be shown, and a way to make it
// meet its workers now rather than waiting for dawn — a muster is ten real
// minutes apart, which no check can sit through.
window.__chief = (i = 0) => {
  const site = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)[i];
  if (!site) return null;
  return {
    site,
    report: () => report(site, chiefCtx, 'dawn'),
    brief: () => brief(report(site, chiefCtx, 'dawn')),
    muster: (which = 'dawn') => runMuster(site, which),
    log: musterLog,
    counter: () => counterOf(site),
    // where this village mines, and the direction to stand to look at it
    mine: () => mineHeadFor(site),
    mineAt: () => {
      const m = mineHeadFor(site);
      if (!m) return null;
      const p = CS.cellCenterWorld(m.f, m.u + m.du * 5, m.v + m.dv * 5, m.h);
      return new THREE.Vector3(p[0], p[1], p[2]).normalize();
    },
    // the model chief's seam, without a model: hand it the same answer the
    // server would broadcast and watch it land
    orders: (answer) => applyChiefAnswer(Ledger.key(site), answer),
    workers: entities.filter((e) => e.village === site && e.forVillage)
      .map((e) => `${e.job}#${e.uid}:${e.order}:${e.state}`),
    // What he says when you ask him, without a mouse. Same list the talk card
    // is built from, answers already worked out — so a check can prove a chief
    // never says anything the player could not have counted for himself.
    say: () => chiefTopics(site).map((t) => ({ q: t.q, a: t.a() })),
    // Talking to it, without a keyboard: what the brief would be, what the
    // steward answers a line with, and the door a model's answer comes in by.
    brief2: () => chiefBriefFor(site),
    ask: (text) => stewardReply(site, String(text)),
    answered: (a) => applyChiefSaid(Ledger.key(site), a),
  };
};
// Raise any missing chiefs now and say what happened. A village with nobody
// THE ALMANAC, and the chronicle behind it. A headless browser cannot press J,
// and the plots are the one part of this that only exists once several days
// have gone by — so there has to be a door to both.
window.__almanac = () => (openAlmanac() ? almanacData() : null);
window.__openArt = (f, u, v, h) => openArt(f, u, v, h);
// THE WEEK AND THE BELL. A headless browser cannot sit through an in-game
// hour, and the whole feature is what happens ON one — so the clock has to be
// settable at a PLACE, not just globally: local noon is a different moment in
// every village on a sphere.
window.__hourAt = (dir) => localHour(new THREE.Vector3(...dir).normalize());
window.__setHourAt = (dir, hour) => {
  const up = new THREE.Vector3(...dir).normalize();
  sunAngle = sunAngleForHour(up, hour) - Math.PI * 2 * 0;
  sunTarget = null;
  sunPinned = true;
  updateSky(0);
  return +localHour(up).toFixed(2);
};
// WHAT THE DARK IS AFRAID OF, and what happens to it in the sun. Neither is
// something a headless browser can watch: one is a list of points and the
// other takes seven seconds of daylight.
window.__lampU = () => ({ n: LIT.uLampN.value, bright: LIT.uLampBright.value,
  lamps: LIT.uLamp.value.slice(0, 6).map((l) => [+l.x.toFixed(1), +l.y.toFixed(1), +l.z.toFixed(1), l.w]),
  gains: [...LIT.uLampGain.value.slice(0, 6)] });
window.__lights = () => ({ near: lightList.length,
  all: lightCells().length,
  atPlayer: !!litNear(player.pos) });
window.__litNear = (pos, keep) => !!litNear(pos, keep);
window.__zombies = () => (entities ?? []).filter((e) => e.kind === 'zombie'
  && !e.dead).map((e) => ({ burning: +(e.burning ?? 0).toFixed(2),
  lit: !!litNear(e.pos), bound: !!e.bound,
  away: +e.pos.distanceTo(player.pos).toFixed(1) }));
window.__putZombie = (dir, arc = 6) => {
  const d = new THREE.Vector3(...dir).normalize();
  const e = spawnZombie(planet, scene, d, {
    minArc: arc, maxArc: arc + 2, entities: null,
  });
  if (!e || e.dead) return false;
  entities.push(e);
  return true;
};
window.__week = () => {
  const day = worldDay();
  return { day, name: dayOfWeek(day).name, prayers: dayOfWeek(day).prayers,
    next: nextPrayer(localHour(player.up), day) };
};
window.__prayFor = (e) => prayFor(e);
window.__cafeFor = (e) => cafeFor(e);
window.__venues = (site) => venuesOf(site);
window.__worshipOf = (s) => worship.get(s) ?? null;
window.__services = () => [...worship.entries()].map(([s, w]) => ({
  village: s.name, hour: w.hour, called: w.called, spots: w.spots.length,
}));
// THE PRIEST. A headless browser cannot aim a crosshair at a man, and what he
// says is the whole feature, so there has to be a door straight to the answers.
window.__priests = () => (entities ?? []).filter((e) => e.job === 'priest'
  && !e.dead).map((e) => ({
  at: e.priest ? [e.priest.f, e.priest.u, e.priest.v, e.priest.h] : null,
  faith: e.priest?.faith ?? null,
  village: villageNear(e.priest?.f ?? 0, e.priest?.u ?? 0, e.priest?.v ?? 0, 110)?.name
    ?? null,
}));
window.__ask = (i = 0) => {
  const who = (entities ?? []).filter((e) => e.job === 'priest' && !e.dead)[i];
  if (!who) return null;
  const site = who.village
    ?? villageNear(who.priest.f, who.priest.u, who.priest.v, 110);
  const office = OFFICES.find((o) => o.role === 'priest');
  return {
    site,
    say: () => office.topics(site).map((t) => ({ q: t.q, a: t.a() })),
    ask: (text) => stewardReply(site, String(text), false, office),
    brief: () => office.brief(site),
  };
};
// Say something to one of a village's offices exactly as the talk card does,
// and wait for whoever answers: the game's AI, another model, or (with nobody
// listening) the steward's own words.
window.__talk = (i = 0, role = 'chief', text = 'how are you doing?') => {
  const site = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)[i];
  const office = OFFICES.find((o) => o.role === role);
  if (!site || !office) return null;
  const key = `${Ledger.key(site)}#${office.role}`;
  return new Promise((done) => {
    const t0 = performance.now();
    const fn = ({ key: k, answer }) => {
      if (k !== key || answer?.waiting) return;
      done({ village: site.name, role, secs: +((performance.now() - t0) / 1000).toFixed(1),
        speech: answer.speech, orders: answer.orders, deal: answer.deal,
        none: answer.none ?? false, why: answer.why ?? null });
    };
    net.on('chiefsaid', fn);
    if (role === 'shop') {
      const deal = readDeal(site, text);
      const struck = deal ? strikeDeal(site, deal) : null;
      if (struck) { done({ village: site.name, role, struck }); return; }
    }
    if (!net?.sendChiefSay?.(key, office.brief(site), text, office.role,
      { name: site.name, world: worldSlot ?? '' })) {
      done({ village: site.name, role, steward: stewardReply(site, text, false, office) });
    }
    setTimeout(() => done({ village: site.name, role, timeout: true }), 120000);
  });
};
window.__artAt = (f, u, v, h) => artAt(f, u, v, h);
window.__CS = CS;
// ONE TILE OUT OF THE ATLAS, as pixels. A texture is the one thing in this
// game a screenshot cannot settle — a stone wall photographed at an angle is
// lighting as much as it is paint — so a check reads the texels the painter
// actually wrote.
// the whole atlas as it stands, for a contact sheet of every tile at once
window.__atlasImage = () => atlas.image;
window.__tile = (name = 'STONE') => {
  const tile = TILE[name];
  if (tile == null) return null;
  const img = tilePixelsOf(atlas, tile);
  const px = [];
  for (let i = 0; i < img.data.length; i += 4) {
    px.push([img.data[i], img.data[i + 1], img.data[i + 2]]);
  }
  return { name, size: Math.round(Math.sqrt(px.length)), px };
};
window.__book = () => almanacData();
window.__ledger = () => ledger;
window.__day = () => worldDay();
window.__chron = (dt = 6) => { chronClock = 0; updateChronicle(dt); };
// Write the dispatch for the day before `day` now, rather than at a dawn no
// check can sit through; hands back the last three.
// A far village's muster now, and what the AI planned for the next one.
window.__paperNow = (i = 0, which = 'dawn') => {
  const site = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)[i];
  if (!site) return null;
  const rec = ledger.of(site);
  paperMuster(site, which, rec);
  return { name: site.name, orders: site.paperOrders, plan: rec.plan };
};
window.__dispatch = (day = worldDay() + 1) => {
  updateDispatch(day);
  return ledger.news.slice(-3);
};

// THE STOCKROOM under a shop: what is in the boxes, what the counter says is
// on the shelf, and the two doors that keep them the same thing.
window.__store = (i = 0) => {
  const sh = (planet?.shopList ?? [])[i];
  if (!sh) return null;
  const st = sh.store;
  const { rows } = shelfOf(sh);
  const boxes = (st?.chests ?? []).map((c) => {
    const ent = blockEntities.get(sh.f, c.u, c.v, c.h);
    return {
      cat: c.cat, block: planet.get(sh.f, c.u, c.v, c.h),
      wool: planet.get(sh.f, c.u, c.v, c.h + 1),
      held: ent ? ent.contents().map((k) => `${k.id}x${k.count}`) : null,
    };
  });
  return {
    shops: planet.shopList.length,
    withStore: planet.shopList.filter((x) => x.store).length,
    at: { f: sh.f, u0: sh.u0, v0: sh.v0, base: sh.base },
    floor: st?.floor ?? null, ladder: st?.ladder ?? null,
    shelf: rows.map((r) => `${r.id}x${r.count}`),
    boxes,
  };
};
window.__openStore = (i = 0, cat = 'food') => {
  const sh = (planet?.shopList ?? [])[i];
  const bay = sh?.store?.chests.find((c) => c.cat === cat);
  if (!bay) return null;
  const ent = blockEntities.ensure(KIND.CHEST, sh.f, bay.u, bay.v, bay.h);
  openContainer(ent);
  return ent.contents().map((k) => `${k.id}x${k.count}`);
};
window.__takeStore = (id, n = 1) => {
  const ent = containerUI.entity?.() ?? null;
  return ent ? ent.remove(id, n) : 0;
};
window.__closeStore = () => { containerUI.close(); return true; };
window.__cui = () => containerUI;
// THE CRAFTING PANEL AND ITS TABS. E is a key, and a key is the one thing a
// headless browser cannot press through a pointer lock — so the panel that
// holds every item in the game had no door a check could open, and the tabs
// down its side could not be proved to contain anything.
window.__craft = {
  open: (bench = false) => { openCrafting({ bench }); return craftUI.isOpen(); },
  close: () => { craftUI.close(); craftingOpen = false; return true; },
  tabs: () => [...document.querySelectorAll('.cui-cat')].map((b) => b.textContent),
  tab: (name) => {
    const b = [...document.querySelectorAll('.cui-cat')]
      .find((x) => x.textContent === name);
    b?.click();
    return !!b;
  },
  shown: () => [...document.querySelectorAll('.cui-book .cui-slot')]
    .map((s) => s.title).filter(Boolean),
};

// THE PEACE. What each village currently thinks of you, and a door to break
// something without having to aim a pickaxe at it from a headless browser.
window.__peace = () => ({
  villages: (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)
    .map((s) => ({
      name: s.name, outlaw: +(s.outlaw ?? 0).toFixed(1), crimes: s.crimes ?? 0,
      soldiers: entities.filter((e) => e.job === 'soldier' && e.village === s
        && !e.dead).length,
    })),
  health: +(combat.health?.hp ?? 0).toFixed(1),
  dead: !!combat.health?.dead,
});
// Swing a pickaxe at one cell, through the real breakBlock — the drops, the
// claim check and the village's temper all included. A headless browser cannot
// aim a crosshair, and every check of the peace that did not go through this
// door would be checking something other than what happens when you mine.
// ...and PLACE into one cell, through the real placeBlock — the held stack,
// the kept-chest unpacking, the bed pairing, all of it. `hit` is the solid
// cell being built against and `prev` the air cell the block lands in, which
// is exactly what the raycast would have answered.
window.__put = (f, u, v, h) => {
  const was = planet.get(f, u, v, h);
  target = { hit: [f, u, v, h - 1], prev: [f, u, v, h], dist: 1 };
  placeBlock();
  target = null;
  return { was, now: planet.get(f, u, v, h) };
};
window.__mine = (f, u, v, h) => {
  const was = planet.get(f, u, v, h);
  target = { hit: [f, u, v, h], prev: null, dist: 1 };
  breakBlock();
  target = null;
  return { was, now: planet.get(f, u, v, h) };
};
// ...and the other half of the same door: RIGHT-click one cell, through the
// real useBlock — the lid, the latch, the counter, the lectern and the bell.
// A headless browser cannot aim a crosshair at a bell on a parapet.
window.__use = (f, u, v, h) => {
  target = { hit: [f, u, v, h], prev: null, dist: 1 };
  const did = useBlock();
  target = null;
  return did;
};
window.__claim = (f, u, v, h) => myWork.add(`${f},${u},${v},${h}`);
// The one door every block change goes through, opened for a check: it is
// what digging a trench with a script has to use, or the edit never reaches
// the diff, the wire, or the water beside it.
window.__set = (f, u, v, h, b) => { setBlock(f, u, v, h, b); return true; };
window.__wrong = (f, u, v, block = BLOCK.PLANK) => {
  const s = wrongVillage(f, u, v, block);
  return s ? { name: s.name, outlaw: +s.outlaw.toFixed(1) } : null;
};

// in charge of it is the one thing this game must never have, so it is worth
// being able to ask.
window.__chiefs = () => {
  const before = entities.filter((e) => e.job === 'chief').length;
  const sites = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai);
  ensureChiefs();
  return {
    sites: sites.length,
    chiefs: entities.filter((e) => e.job === 'chief').length,
    raised: entities.filter((e) => e.job === 'chief').length - before,
    seated: sites.filter((s) => s.seat).length,
    missing: sites.filter((s) => !s.chief).map((s) => s.name),
  };
};
// THE ENVOY. A muster comes round every ten real minutes and a journey takes
// a couple of in-game ones, so no check can sit and wait for a chief to decide
// to send somebody. This is the same door landOrders opens — sendWord, with
// the village picked the same way — worked by hand.
// WAR, by hand. A raid is a chief's decision at a muster, and no check can
// sit through one — so this is the same door landOrders opens (startWar, the
// target picked the same way) worked from the console, plus a way to read how
// the fighting is going while it runs.
// THROWN CHARGES, by hand. A fuse is three seconds and a check cannot click
// a mouse, so this is the same door tryThrow opens: aim it where the player
// is looking (or down a given vector) and watch it land, count down and go.
// THE CIRCUIT, for a check that cannot flick a lever. `__power()` says what
// is laid and what is live; `__switch(f,u,v,h)` throws one.
// THE LINE, for a check that cannot press B. `__wagon()` says where the carts
// are and which one is being ridden; `__ride()` gets in or out.
window.__wagon = () => ({
  carts: wagons().map((w) => ({
    pos: w.pos.toArray().map((x) => +x.toFixed(1)),
    speed: +w.speed.toFixed(2),
    rail: w.rail ? { f: w.rail.f, u: w.rail.u, v: w.rail.v, h: w.rail.h,
      axis: w.rail.axis } : null,
  })),
  riding: !!ridingWagon(),
});
window.__putWagon = (f, u, v, h) => !!placeWagon(scene, planet, f, u, v, h);
window.__ride = () => { toggleWagon(player); return !!ridingWagon(); };
// which piece a rail laid at this cell would become — the placement's own
// neighbour test, checkable without aiming a mouse
window.__railPiece = (f, u, v, h) => railPieceFor(f, u, v, h, CS.railId(0));

window.__power = () => ({
  blocks: [...powerCells.values()].map((c) => ({
    ...c, b: planet.get(c.f, c.u, c.v, c.h) })),
  live: [...powerLive],
  doors: [...poweredDoors],
});
window.__switch = (f, u, v, h) => toggleSwitch(f, u, v, h);
window.__repower = () => { powerDirty = true; updatePower(0); return powerLive.size; };

window.__throw = (id = 'dynamite', dir = null) => {
  const spec = getItem(id);
  if (!spec?.throwable) return { why: 'not a throwable' };
  const d = dir ? _wk.set(...dir).normalize() : _wk.copy(player.lookDir).normalize();
  const ok = combat.throwCharge(player.eye ?? player.pos, d, spec);
  return { thrown: ok, fuse: spec.fuse, blast: spec.blast };
};
window.__charges = () => combat.projectiles.filter((p) => p.fuse != null)
  .map((p) => ({ fuse: +p.fuse.toFixed(2),
    at: p.pos.toArray().map((v) => +v.toFixed(1)),
    speed: +p.vel.length().toFixed(2) }));

window.__war = (i = 0, j = null) => {
  const sites = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai);
  const from = sites[i];
  if (!from) return null;
  const to = j == null ? warTarget(from) : sites[j];
  if (!to) return { why: 'no neighbour' };
  const out = startWar(from, to);
  return { from: from.name, to: to.name, ...out };
};
// The muster on paper, by hand: a far village's book after one, and the raid
// it might roll for. See paperMuster and paperRaid.
window.__paper = (i = 0, which = 'dawn') => {
  const site = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)[i];
  if (!site) return null;
  const rec = ledger.of(site);
  paperMuster(site, which, rec);
  return { name: site.name, souls: rec.souls, bought: rec.bought,
    orders: site.paperOrders, musters: rec.musters };
};
window.__paperRaid = (i = 0) => {
  const site = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)[i];
  if (!site) return null;
  site.warCool = 0;
  return paperRaid(site, worldDay(), ledger.of(site));
};
// Village growth by hand: one pass of growWorld and what it was working from.
window.__grow = () => {
  const built = growWorld();
  return { built, grownTo, growing, day: worldDay(),
    sites: (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)
      .map((s) => [s.name, s.grown ?? null, s.shortOf ?? null]) };
};
// What the GPU is holding: three.js's own count of live geometries, textures
// and programs. A number that climbs while the chunk count does not is a
// mesh somebody forgot to dispose — the one kind of leak no heap size shows.
window.__gpu = () => ({ ...renderer.info.memory,
  programs: renderer.info.programs?.length ?? 0,
  heapMB: performance.memory
    ? +(performance.memory.usedJSHeapSize / 1048576).toFixed(0) : null,
  chunks: world?.chunkGroup?.children?.length ?? 0,
  queue: world?.queue?.length ?? 0,
  scene: scene.children.length,
  entities: entities.length,
  anims: blockAnimCount?.() ?? null,
});
window.__wars = () => ({
  log: warLog.slice(0, 6),
  live: (planet?.villageSites ?? []).filter((s) => s.warOn || s.besieged > 0)
    .map((s) => ({
      name: s.name,
      marchingOn: s.warOn?.name ?? null,
      besieged: Math.round(s.besieged ?? 0),
      left: Math.round(s.warT ?? 0),
      party: (s.warParty ?? []).map((e) => ({
        uid: e.uid, dead: !!e.dead,
        arrived: !!e.war?.arrived, back: !!e.war?.back,
      })),
    })),
  purses: (planet?.villageSites ?? []).filter((s) => s.name && !s.serai)
    .map((s) => ({ name: s.name, purse: ledger.of(s)?.purse ?? 0 })),
});

window.__envoy = (i = 0, howMany = 1, toName = null) => {
  const sites = (planet?.villageSites ?? []).filter((s) => s.name && !s.serai);
  const site = sites[i];
  if (!site) return null;
  const to = envoyTarget(site, toName);
  if (!to) return { from: site.name, to: null, sent: 0, why: 'no neighbour' };
  const spare = entities.filter((e) => !e.dead && e.village === site
    && e.kind === 'villager' && !e.shop && !e.errand && !e.hired
    && e.job !== 'chief' && e.job !== 'priest' && e.job !== 'trader');
  const sent = [];
  for (const e of spare.slice(0, howMany)) {
    if (sendWord(e, site, to)) sent.push(`${e.job}#${e.uid}`);
  }
  return { from: site.name, to: to.name, spare: spare.length, sent,
    news: villageWord(site), hall: !!hallDirOf(to) };
};
// Everybody currently on a road, and how their journey is going. `gap` is how
// far they still are from whatever they are walking at, and `stale` is the
// give-up clock — the two numbers the whole design turns on.
// Everybody alive, nearest first — the list a check needs before it can point
// at anybody. The order card is a crosshair gesture; this is how a harness
// finds something to put the crosshair on.
// Your stores, and the one a given hand would walk a load to. Where a day's
// work ENDS UP is the hardest thing in this game to see from a screenshot.
window.__spots = () => ({
  set: (id, dir = null) => markSpot(id, dir ? new THREE.Vector3(...dir) : player.up),
  clear: (id, i = null) => clearSpot(id, i),
  all: () => [...spots.entries()].map(([id, list]) => ({ id, places: list })),
  dirOf: (id, n = 0) => spotDir(id, n),
});
window.__depot = (e = null) => ({
  mine: myChests().map((c) => ({ f: c.f, u: c.u, v: c.v, h: c.h })),
  range: DEPOT.range,
  forHand: e ? depotOf(e) : null,
  holds: (c) => blockEntities.get(c.f, c.u, c.v, c.h)?.contents?.() ?? null,
});
// The autosave, without the minute. A check cannot sit through sixty seconds
// of a headless renderer running at four frames a second — the clock counts
// frame dt, so a real minute of it is five minutes of waiting.
window.__autosaveNow = () => { autoClock = 0; return AUTOSAVE; };
// Mark out the house you have ordered, now, without waiting for the clock or
// for a hand to look again. Returns what stopped it if anything did.
window.__buildNow = (e = null) => {
  const who = e ?? myHands().find((x) => x.order === 'build') ?? myHands()[0];
  if (!who) return 'nobody to build';
  const r = myHousePlot(who, 0);
  return { started: !!r, why: who.why0 ?? null, rising: rising.length };
};
// The on-screen controls. They hide themselves on anything with a mouse, so a
// check on a desktop browser cannot see them at all — `show` forces them up so
