// EVERY VILLAGE HAS A PRESS, and this is what counts them. A settlement gets
// its mint from its shop — see `shop` in village.js — and every settlement has
// a shop now, the lake people included: theirs stands on a plot along the plank
// walk with a keeper and a cellar under it.
//
// The question is still asked of the SITE and answered off the BLOCKS, for two
// reasons that outlive the counter. A fen village whose lake is too small or
// too crowded to take a shop still falls back to the jetty press — see the
// press in `buildFenVillage` — so the shop list is not the whole of the answer even
// today. And a press that is IN a list but not in the ground is exactly the
// failure this hook exists to catch: it scans the way work.js's own findMint
// scans, so what it counts is what a worker sent to strike coin would actually
// walk to.
window.__mints = () => {
  const rows = (planet?.villageSites ?? [])
    .filter((s) => s.name && !s.serai).map((s) => {
      let hit = null;
      for (let du = -70; du <= 70 && !hit; du++) {
        for (let dv = -70; dv <= 70 && !hit; dv++) {
          const u = s.u + du, v = s.v + dv;
          if (u < 1 || v < 1 || u >= CS.S - 1 || v >= CS.S - 1) continue;
          const top = planet.columnTop(s.f, u, v);
          for (let h = top; h > top - 16 && h > 1; h--) {
            if (planet.get(s.f, u, v, h) === BLOCK.MINT) {
              hit = { f: s.f, u, v, h };
              break;
            }
          }
        }
      }
      return { name: s.name, fen: !!s.fen, mint: hit };
    });
  return {
    villages: rows.length,
    withMint: rows.filter((r) => r.mint).length,
    without: rows.filter((r) => !r.mint).map((r) => r.name),
    // ...and where each one stands, because a count is not a look at one
    rows,
  };
};
// Every village's name and where it says so — the boards are canvas quads,
// so a screenshot is the only other way to read one.
// Where a name board actually hangs, in world space. The board is a canvas
// quad on the outside of a block, so a check that wants to look at one has to
// be told where it is rather than guessing from the cell.
window.__boardOf = (sg) => {
  const n = new THREE.Vector3(...sg.out).normalize();
  const p = CS.cellCenterWorld(sg.f, sg.u, sg.v, sg.h);
  return new THREE.Vector3(p[0], p[1], p[2]).addScaledVector(n, 0.53);
};
window.__signs = () => ({
  meshes: signMeshes.length,
  villages: (planet?.villageSites ?? []).map((s) => ({
    name: s.name, boards: s.signs?.length ?? 0, f: s.f, u: s.u, v: s.v,
  })),
});
// Your company, and the card that commands it. The order card is a pointer
// gesture at a moving animal, which a harness cannot make; this is the same
// three verbs with the pointing taken out.
window.__company = () => ({
  ui: orderUI,
  list: company().map((e) => ({
    e, kind: e.kind, job: e.job, order: e.order, hired: !!e.hired,
    state: e.state, dist: +e.pos.distanceTo(player.pos).toFixed(1),
    carry: e.carry ?? null,
  })),
  tame: (e) => tame(e, player),
  hire: (e) => (hire(e, player) ? (enrol(e), true) : false),
  // ...and through the door the PLAYER uses, price, bed cap and all — the
  // crosshair taken out, because a harness cannot point at a moving man.
  take: (e) => !!takeOn(e),
  name: (e, n) => {
    const row = roster.get(e?.hid);
    const clean = String(n ?? '').trim() || null;
    if (row) row.name = clean;
    if (e) e.title = clean;
    return clean;
  },
  order: (id, list = null) => {
    for (const e of list ?? company()) e.setOrder(id, e.up);
    return company().map((e) => e.order);
  },
  sic: (foe, list = null) => {
    for (const e of list ?? company()) e.sic(foe);
  },
  // WHO THE CROSSHAIR IS ON, which is the one thing an order card cannot be
  // checked without: the difference between "tell this man" and "tell
  // everybody" is entirely this answer. See aimedEntity.
  aimed: () => aimedEntity(ORDER_REACH,
    (e) => e.owner === player && (e.tamed || e.hired)),
  // Who is standing about that you could take on, nearest first. The card is
  // opened by pointing and `take` wants a person: this is the only way a
  // check has of naming one.
  near: (n = 8) => entities
    .filter((e) => e.kind === 'villager' && !e.dead && !e.hired
      && e.owner !== player && canHire(e))
    .sort((a, b) => a.pos.distanceTo(player.pos) - b.pos.distanceTo(player.pos))
    .slice(0, n),
  // ...and the mouse, for a check that has none: turn on the spot by this many
  // radians. Same door the pointer uses — see onMouse in js/player.js.
  turn: (rad, pitch = null) => {
    player.turnBy(rad, pitch);
    player.syncCamera();
    return player.lookDir.toArray();
  },
  open: () => openOrders(),
});
// The houses going up right now: how far through each script is, and who is
// standing on the plot. A build takes a minute of real time, so a check needs
// to be able to see it half done rather than only before and after.
window.__rise = () => rising.map((r) => ({
  kind: r.kind, at: r.i / 6, of: r.writes.length / 6,
  f: r.f, u0: r.u0, v0: r.v0, w: r.w, d: r.d,
  // How many of the village's own people are on the plot right now. A plot
  // with none does not move at all — see updateRising.
  hands: r.hands ?? 0, crew: r.crew ?? 0, done: +r.done.toFixed(1),
  site: r.site?.name ?? null,
  // whose plot it is, and how far each of the player's own is from its
  // middle — the two things that decide whether it moves at all
  mine: !!r.mine,
  away: (entities ?? []).filter((e) => !e.dead && e.order === 'build')
    .map((e) => +(e.pos.angleTo(_v3.set(...(r.plotDir ?? r.dir)).normalize()
      .multiplyScalar(R0 + (r.base ?? 1) + 1)) * e.pos.length()).toFixed(1)),
}));
// The gang, and what each of them is doing about it: where they are stood
