// The world goes through the vertex shader; everything that MOVES over it has
// to be re-placed to match, or a villager twenty paces off stands a block deep
// in ground that is no longer where he thinks it is. Their own geometry is
// left alone — half a metre of villager does not curve measurably — so this is
// one position and one swing rotation each, after they have all had their say.
//
// It runs whether the horizon is flat or not, and that is the whole of the
// fix it carries. It used to return early on a round horizon, which meant
// nothing ever undid the displacement: the projection maps a creature on the
// far side of the world onto a plane at your feet, so leaving play with the
// flat horizon on — and it is on by default — left the villagers hanging in
// the sky over the globe, a hundred blocks off the ground, because syncMesh
// only runs for creatures near a player who is no longer in the world. On a
// radius-78 planet that was 39 of 45 of them, the worst 164 blocks out.
//
// Nothing here accumulates, either. flattenObject PREMULTIPLIES a rotation,
// so a mesh that was not re-placed first would have been turned again every
// frame it stayed on screen.
const flatHold = new WeakMap();   // mesh -> its true transform while displaced

function placeLoose() {
  const flat = flatten.isFlat();
  // How far a body may be and still be handed to the shadow passes. Same
  // argument as the chunks (see cull in cubemesher.js): a villager four
  // hundred blocks off cannot cast into a box that is a hundred wide, and
  // every one of his fifteen boxes was being offered to every pass anyway —
  // six and a half THOUSAND casters in a scene on a large world, which is a
  // frame rate low enough that the camera's own smoothing reads as a shake.
  //
  // Flipped only when it CHANGES: walking the parts of every entity every
  // frame to write a flag they already hold is the cost this is avoiding.
  const castR2 = (SHADOW.reach * 1.2) ** 2;
  // How far a body is worth DRAWING, let alone shading. The frame on a big
  // world is not the terrain — it is four hundred rigs of fifteen boxes,
  // every box six draw groups, posed and submitted every frame whether they
  // are four blocks away or four hundred. Three tiers, by distance:
  //
  //   0  near      full pose, drawn, casts its shadow
  //   1  far       drawn, but the limbs re-pose on a quarter of the frames —
  //                at that size on screen a 15Hz walk cycle is not a thing
  //                anyone has ever noticed
  //   2  distant   not drawn at all. The simulation underneath runs exactly
  //                as before — AI, work, courting, combat all read e.pos,
  //                never the mesh — so the village a hundred blocks on keeps
  //                living; you just stop paying to draw its walkers as
  //                sub-pixel specks
  //
  // The boundaries carry hysteresis so a body pacing on the line does not
  // flicker in and out of existence.
  for (const e of entities) {
    if (!e.mesh || !e.pos) continue;
    const d2 = e.pos.distanceToSquared(player.pos);
    const lod = e._lod ?? 0;
    e._lod = d2 < (lod === 0 ? ENT_LOD.near * 1.1 : ENT_LOD.near) ** 2 ? 0
      : d2 < (lod === 2 ? ENT_LOD.draw : ENT_LOD.draw * 1.1) ** 2 ? 1 : 2;
    const shown = e._lod < 2;
    if (e.mesh.visible !== shown) e.mesh.visible = shown;
    if (!shown) continue;                 // nothing below costs a hidden body
    e.placeMesh();                        // truth first, every frame
    if (flat) flatten.flattenObject(e.mesh, e.pos);
    const near = d2 < castR2;
    if (near !== e._casting) {
      e._casting = near;
      e.mesh.traverse((o) => { if (o.isMesh && o.userData.casts) o.castShadow = near; });
    }
  }
  // a stack lying on the grass is one of these too: it keeps a true position
  // and is re-placed on the CPU, so it does not slide off the hill it fell on
  for (const d of groundItems) placeDrop(d, flat);
  placeFalling(flat);   // ...and every block still on its way down
  // The village name boards are NOT here: their material goes through the
  // flatten shader with the terrain (see buildVillageSigns), so they need no
  // CPU re-placement and never move at all.
  // Fish keep no position of their own — the mesh IS the record — so theirs
  // is stashed before it is overwritten and handed back afterwards. (The
  // city's cars used to be here too; the city is on foot now.)
  const loose = [];
  for (const f of liveFish()) if (f.mesh) loose.push(f.mesh);
  for (const mesh of loose) {
    if (flat) {
      flatHold.set(mesh, {
        pos: mesh.position.clone(), quat: mesh.quaternion.clone(),
      });
      flatten.flattenObject(mesh, mesh.position.clone());
    } else {
      const held = flatHold.get(mesh);
      if (held) {
        mesh.position.copy(held.pos);
        mesh.quaternion.copy(held.quat);
        flatHold.delete(mesh);
      }
    }
  }
}

// ---- multiplayer -----------------------------------------------------------
// The transport (net.js) and the bodies/panel (netui.js) predate this wiring;
// INTEGRATION-net.md is the contract. With no server reachable every call in
// here is a no-op and the game is byte-for-byte the single-player game.

const net = new Net({
  name: 'player', tickHz: 10,
  // read at connect time: the skin is whatever the player is wearing
  look: () => player.look,
});
let remotes = null;

// Multiplayer is not a switch any more: the world you are standing in is the
// world on offer, from the moment it exists. There is nothing to press and
// nothing to remember to press — you make a world, and the address in the
// "play together" panel is a door into that one.
//
// Silent when there is nobody to offer it to. Opened from plain serve.py, or
// from a file:// URL, there is no relay behind the page and this does nothing
// rather than reporting a failure at something the player never asked for.
function offerWorld() {
  if (!planet || !netui?.canHost?.()) return false;
  const url = Net.ownUrl();
  if (!url) return false;
  net.name = netui.playerName();
  net.look = player.look;
  net.connect(url, {
    radius: R, seed: worldSeed, preset: worldPreset,
    style: currentStyle().id,
    // The designs this world's villages were laid out from go up with it, for
    // the same reason the preset does: a friend whose blueprints/ folder holds
    // different designs would otherwise generate different villages in the
    // same named world, and walk into a shop that is not where yours is.
    designs: worldDesigns.length ? designDocs() : null,
    // ...and the generation of its terrain, on the same terms
    terrain: worldTerrain,
    // the mode goes up with the world it belongs to, so joiners land in the
    // game this world is being played as — attack stays attack for everyone
    mode: gameMode,
    // ...and this one replaces whatever the server was holding. See
    // claim_world in server.py: without it, only the first world of the
    // session was ever shared and every one after it was private.
    host: true,
  });
  return true;
}

// The server's corner: what its terminal used to say, small, bottom-left.
// The window launcher runs the server with no console at all now, so the
// join URLs and the last few log lines live here instead. Fed by netui's
// /net-info probe every five seconds; hidden in first person by CSS.
const serverInfoEl = document.getElementById('serverInfo');
function renderServerInfo(info) {
  if (!serverInfoEl) return;
  if (!info) { serverInfoEl.style.display = 'none'; return; }
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
  const urls = (info.lan?.length ? info.lan : ['localhost'])
    .map((ip) => `join: http://${ip}:${info.port}`);
  const mins = Math.max(0, Math.floor((info.uptime ?? 0) / 60));
  const n = info.players | 0;
  const head = [
    `PlanetCraft server · ${n} player${n === 1 ? '' : 's'} · `
    + `${info.edits | 0} edits · up ${mins}m`,
    ...urls,
  ];
  const log = (info.log ?? []).slice(-6);
  serverInfoEl.innerHTML = head.map(esc).join('\n')
    + (log.length ? `\n<span class="dim">${log.map(esc).join('\n')}</span>` : '');
  serverInfoEl.style.display = 'block';
}

netReady = true;      // `net` exists from here on — see CHIEF_HOOKS above

const netui = new NetUI({
  net,
  onInfo: renderServerInfo,
  // What to propose if we are the first one in: whatever the menu has. The
  // preset goes with the radius and the seed because the planet is a function
  // of all three — proposing two of them and letting the third default is
  // exactly how a joiner ended up on a differently-generated world.
  worldWish: () => ({
    radius: planet ? R
      : Number(document.querySelector('#menu .size.sel')?.dataset.r ?? 78),
    seed: planet ? worldSeed : Math.floor(Math.random() * 1e9),
    preset: planet ? worldPreset : chosenPreset(),
    // ...and the terrain's generation: this world's, or the newest for a
    // world that does not exist yet
    terrain: planet ? worldTerrain : CS.TERRAIN_LATEST,
    style: currentStyle().id,
    // the mode rides along so a joiner lands in the game the host is
    // playing — an attack server hands everyone the attack rules, not
    // whatever their own menu happened to have selected
    mode: gameMode,
  }),
  onMessage: flash,
  // where I am, for the online panel's "42 blocks away" column
  localPos: () => (player.pos.lengthSq() > 1e-6 ? player.pos : null),
  onFriends: () => {
    remotes?.refresh();                    // nameplates bake their colour
    for (const [id, m] of miniPlayers) {   // and so do the globe markers
      miniScene.remove(m);
      m.geometry.dispose();
      m.material.dispose();
      miniPlayers.delete(id);
    }
  },
  // Fires on welcome, which is also where a reconnect lands, so it is
  // idempotent: rebuild only when the planet is genuinely a different one.
  onWorld: (w) => {
    // The server's world wins, whole: radius, seed AND preset. Leaving the
    // preset out of this test is what let the person who created the world
    // keep their own terrain while everyone joining generated `terran` from
    // the same seed — one world by name, two by geography.
    const preset = w.preset ?? 'terran';
    const mine = !!planet && R === w.radius && worldSeed === w.seed
      && worldPreset === preset && worldTerrain === (w.terrain ?? 1);
    if (mine) {
      // Our own world, come back to us: we offered it and the server took
      // it. There is nothing to rebuild, and nothing here may touch the
      // mode, the look or the art — they are already the ones this world
      // was made with, and re-reading them off the menu would undo, for
      // instance, the designer mode a flat world just switched itself into.
      //
      // What DOES have to happen is the other direction: everything already
      // built here has to go up, or a friend walks into bare terrain where
      // your house is.
      for (const [key, b] of edits) {
        const p = key.split(',');
        net.sendEdit(+p[0], +p[1], +p[2], +p[3], b);
      }
    } else {
      // the world's own mode wins when the server knows it; the joiner's
      // menu selection is only the fallback for older servers
      setGameMode(w.mode
        ?? document.querySelector('#modes .mode.sel')?.dataset.mode
        ?? 'survival');
      // The art is the world's too, so you arrive seeing what they see. Y
      // still cycles it afterwards; this is the starting point, not a lock.
      // It must land BEFORE buildWorld, which paints the atlas from the
      // current style.
      if (w.style) selectStyle(w.style);
      // Whose planet this is, before it is built. buildWorld records what the
      // resident body was made from (see planetSeeds), so a world walked into
      // over the wire has to say which body it IS or it files the host's seed
      // against wherever we happened to be standing — and the next flight
      // home lands on their planet instead of ours.
      currentPlanet = systemBodies().find((p) => p.preset === preset)
        ?? currentPlanet;
      // The host's designs, not ours. An older server sends none and we fall
      // back to our own library, which is the behaviour this replaces.
      buildWorld(w.radius, w.seed, w.edits, preset, null,
        w.designs ? w.designs.map(blueprint.decode) : blueprints.slice(),
        w.terrain ?? 1);
      // Somebody else's world is not one of yours: pressing save must not
      // write it over the slot of the last world you actually made.
      worldSlot = null;
    }
    // And the same time of day as everybody else, from this instant — with
    // one exception, which is OUR OWN world coming back to us.
    //
    // `sunAngle` is unwrapped, so it is the DATE as well as the hour, and the
    // chronicle is written against worldDay() = floor(sunAngle / 2π). A server
    // that has just been restarted claims a fresh world at 0.7. Taking that on
    // a world we have just loaded threw the clock back to day zero, and the
    // almanac then looked as though it had forgotten everything — the rows
    // were all still on the books, filed under days the world was about to
    // live through a second time.
    //
    // So: somebody else's world sets our clock, because theirs is the one that
    // counts. Our own world only ever winds FORWARD, and if the server is
    // behind us we tell it the date instead of taking its word for it — the
    // same rule, and the same direction, as set_sun in server.py.
    if (typeof w.sun === 'number') {
      if (!mine || w.sun > sunAngle) { sunAngle = w.sun; sunTarget = w.sun; }
      else { sunTarget = null; net.sendSun?.(sunAngle); }
    }
    // ...and the same money. After buildWorld, which clears the books for the
    // incoming world — the server's copy is the one that counts, because it
    // is the one that survived everybody logging off.
    //
    // MERGED, NOT LOADED, and this is the line that lost a player their
    // village. A settlement you founded is on YOUR books and on nobody
    // else's until something ships it; the welcome arrives after the save
    // has been restored and used to hand the server's copy straight to
    // `load`, which replaces. Ten rows in, nine out, and the one that went
    // was the only village they lived in — back with a null count, which
    // reads downstream as "nobody has ever lived here" and gets a nought
    // written over it. See Ledger.merge.
    if (w.ledger) { ledger.merge(w.ledger); shipLedger(); }
    if (w.art) loadArt(w.art);
    if (w.signs) signs.load(w.signs);
    // the server remembers where this player stood when they last left;
    // enterPlay applies it exactly the way a loaded save is applied
    if (w.spawn && !w.resumed) {
      pendingSpawn = { pos: w.spawn.p, forward: w.spawn.f, pitch: w.spawn.a };
    }
    remotes ??= new RemoteAvatars(scene, net, {
      atlas, isFriend: (p) => netui.isFriend(p.pid),
      // What WE are wearing, for the announcement that goes out to everybody
      // else. A getter and not a value: the four keys change whenever a piece
      // is put on or breaks, and net.js sends only when they differ.
      armour: () => player.worn,
    });
    combat.setEntities(() => [...entities, ...pvpTargets()]);
    // ...and straight onto the planet, but only when this welcome actually
    // took us somewhere. JOINING used to leave you parked at the orbit view
    // with nothing saying it had worked, which is what this is for.
    //
    // It must not fire for our own world. Every world is hosted now, so the
    // welcome comes back for worlds we just built as well — and then this
    // would skip the overview you make a planet to look at, and would throw
    // you out of the menu and into the game on any reconnect that happened
    // while you were reading it.
    if (!mine) {
      menu.style.display = 'none';
      enterPlay(false);
    }
  },
});

net.on('edit', ({ f, u, v, h, b }) => {
  if (planet) applyRemoteEdit(f, u, v, h, b);
});

// The shared clock's periodic correction. Only ever a target — updateSky
// closes the gap — so a late or missed one costs nothing.
// Never backwards: see onWorld above. The correction exists to close drift
// between clients, and drift is always the local clock running slow — an angle
// BEHIND ours is a server that has restarted, and following it would undo a
// day the chronicle has already written down.
net.on('sun', (a) => { if (!sunPinned && a > sunAngle) sunTarget = a; });
// Somebody else traded. Whole books — but merged rather than loaded, because
// a row this machine has and the sender does not is a village founded here
// and not yet shipped, and replacing would throw it away. See Ledger.merge.
net.on('ledger', (books) => ledger.merge(books));
// Somebody else hung a picture. One cell, so one chunk to rebuild.
net.on('art', ({ cell, art }) => {
  artChoice.set(cell, art);
  const [f, u, v] = cell.split(',').map(Number);
  if (Number.isFinite(f)) world?.markEdit(f, u, v);
});
// Somebody else wrote on a sign. Quiet, or it would go straight back out.
net.on('sign', ({ cell, text }) => signs.set(cell, text, { quiet: true }));
// A model chief has answered a muster. See applyChiefAnswer — and rule 4:
// if this message never comes, the steward's orders stand and the game plays
// exactly as it does with no key and no network.
net.on('orders', ({ key, answer }) => applyChiefAnswer(key, answer));
// ...and a chief answering a person. Same order list, different door out: the
// words go into the card that asked rather than past on the flash line.
net.on('chiefsaid', ({ key, answer }) => applyChiefSaid(key, answer));
// Alone again: the sun goes back to being ours.
// ...and newly arrived: the server has no idea who should be running the
// villages until it is told, and it is told once per connection rather than
// stored, so a key lives only as long as somebody is playing.
net.on('status', ({ status }) => {
  renderChiefSign();
  if (status !== 'online') { sunTarget = null; return; }
  shipChiefCfg();
  // ...and ask how the chief is. Free — it is the state the server already
  // holds, not a call to anybody — and it is what puts a true answer on the
  // front screen the moment there is a server to ask.
  net.sendChiefStat?.();
});
net.on('dispatch', (m) => applyDispatch(m.day, m.a, m.by));
net.on('paperplan', (m) => applyPaperPlan(m.key, m.plan, m.by));
net.on('chiefstat', (st) => {
  chiefState = st;
  renderChiefSign();
  chiefUI?.showState?.(st);
});

// --- the other players on the globe minimap --------------------------------
// One small sphere per remote player, parented to miniScene (not the camera),
// so it rides the globe as it turns under the player-centred mini camera and
// is occluded by the far side — exactly like the terrain it stands on.

const miniPlayers = new Map();   // net id -> marker mesh

function updateMiniPlayers() {
  if (net.connected) {
    for (const [id, p] of net.players) {
      if (!p.ready) continue;
      let m = miniPlayers.get(id);
      if (!m) {
        m = new THREE.Mesh(
          new THREE.SphereGeometry(0.045, 8, 6),
          new THREE.MeshBasicMaterial({
            color: netui.isFriend(p.pid) ? 0xffd24a : 0x4da3ff,
          }));
        miniScene.add(m);
        miniPlayers.set(id, m);
      }
      if (CS.FLAT) {
        // the map is the [-1, 1] quad; a marker floats just above it
        const k = 2 / S;
        m.position.set(p.pos[0] * k, 0.03, p.pos[2] * k);
      } else {
        const len = Math.hypot(p.pos[0], p.pos[1], p.pos[2]) || 1;
        m.position.set(p.pos[0] / len, p.pos[1] / len, p.pos[2] / len)
          .multiplyScalar(1.02);
      }
    }
  }
  for (const [id, m] of miniPlayers) {
    if (!net.connected || !net.players.has(id)) {
      miniScene.remove(m);
      m.geometry.dispose();
      m.material.dispose();
      miniPlayers.delete(id);
    }
  }
}

// --- PvP -------------------------------------------------------------------
// Hits are detected by the ATTACKER's client — the same trace that hits a
// zombie hits a remote body — and applied by the VICTIM's, whose own
// PlayerHealth is the one door every kind of damage already goes through, so
// creative-mode immunity and i-frames come for free. The server just relays.

const pvpAdapters = new Map();   // net id -> the {mesh, damage()} combat wants

function pvpTargets() {
  if (!remotes || !net.connected) return [];
  const out = [];
  for (const [id, a] of remotes.avatars) {
    const p = net.players.get(id);
    if (!p?.ready || !a.group.visible) continue;
    let ad = pvpAdapters.get(id);
    if (!ad) {
      ad = {
        kind: 'player', dead: false, mesh: a.group,
        hitCentre: 0.95, hitRadius: 0.55,
        // struck: tell them. Never killed from this side — their client owns
        // their health — so this returns false and drops no loot.
        damage: (amount) => {
          net.sendEvent({ kind: 'hit', to: id, dmg: amount });
          return false;
        },
      };
      pvpAdapters.set(id, ad);
    }
    ad.mesh = a.group;      // the avatar rebuilds when looks or friends change
    ad.name = p.name;
    out.push(ad);
  }
  for (const id of [...pvpAdapters.keys()]) {
    if (!net.players.has(id)) pvpAdapters.delete(id);
  }
  return out;
}

net.on('event', (msg) => {
  if (msg.kind === 'hit' && msg.to === net.id) {
    if (mode !== 'play') return;
    const attacker = net.players.get(msg.id)?.name ?? 'someone';
    const dmg = Math.max(0, Math.min(20, Number(msg.dmg) || 0));
    const died = combat.health.damage(dmg, { source: 'pvp' });
    if (!combat.creative) {
      audio.play('playerHurt', {});
      combat.kick.pitch += 3;
      combat.give.pitch += 3 * combat.recover;
    }
    if (died) {
      netui.say(`you were slain by ${attacker}`);
      net.sendEvent({ kind: 'die', by: msg.id });
    }
  } else if (msg.kind === 'die') {
    const who = net.players.get(msg.id)?.name ?? 'someone';
    netui.say(msg.by === net.id ? `you killed ${who}`
      : `${who} was slain by ${net.players.get(msg.by)?.name ?? 'someone'}`);
  }
});

const clock = new THREE.Clock();
// The longest step the world is ever advanced by, however long the frame
// actually took.
//
// Without this, one slow frame is a slow frame AND a broken one. A chunk that
// takes a second to build hands the whole loop dt = 1, and everything scaled
// by dt takes a second's worth of it in one go: edgeTurn is 1100 mouse-pixels
// a second, so the view whips a full turn and a half; a villager crosses a
// field in a step; the water jumps a metre. That is what "it goes funny and
// starts going everywhere" is — not the stutter itself but what the game does
// with the stutter, and it is why it only showed on the bigger planets.
//
// player.update has clamped its own physics to 0.1 s for as long as it has
// existed, for exactly this reason. This is the same statement made once, for
// everything else in the frame. A hitch now costs a moment of slow motion,
// which is what every other game does with one.
const MAX_STEP = 0.1;
// The last two seconds of frame times, in milliseconds. A jitter that is
// really a frame-rate problem and a jitter that is really a geometry problem
// look identical from the outside and are told apart instantly by this.
const frameLog = new Float32Array(120);
let frameAt = 0;
// The WORLD frame's own counts, sampled the moment it is drawn.
//
// renderer.info resets at the start of every render(), and the minimap is
// rendered after the world — so reading it at the end of a frame reports the
// minimap and nothing else. The first dump off a player's machine came back
// saying three draw calls, which is exactly how this was found.
const worldFrame = { calls: 0, triangles: 0 };
// --- fast forward -----------------------------------------------------------
//
// A village day is twenty real minutes, so watching anybody go to bed and get
// up again is twenty minutes of standing still — which is why "do they
// actually reach a bed?" has been an open question rather than something you
// could simply go and look at.
//
// The world runs extra passes; YOU do not. Player physics, the camera, mining
// and placing all stay at one times, so the game is still playable while the
// sun tears across the sky — it is a fast world, not a fast player.
//
// Extra whole PASSES at the true dt rather than one pass with dt multiplied:
// every walker in this game integrates its own position, and handing a
// villager a tenth of a second in one go is how they walk through walls. This
// is the same thing window.tick does, for the same reason.
const TIME_SCALES = [1, 2, 5, 10, 20, 50, 100];
// How long a frame may spend running the world forward, in milliseconds.
//
// The multiplier is whole extra PASSES at the true dt — that is the whole
// design, because every walker here integrates its own position and handing a
// villager a tenth of a second in one go is how they walk through walls. At
// ×10 that is nine extra passes and nobody notices. At ×100 it is ninety-nine
// passes over every entity, every crop, every job and every village on the
// clock, and the frame simply stops coming.
//
// So the multiplier is a TARGET and this is the ceiling. A frame runs as many
// passes as it can afford and then gives up and draws; ×100 on a machine that
// cannot manage it quietly becomes whatever that machine can, instead of
// locking up. The rate you actually get is reported back on the button.
const STEP_BUDGET_MS = 12;
let timeScale = 1;

function stepWorld(dt) {
  if (mode === 'play') {
    updateEntities(dt);
    syncRider();
    updateFarming(dt);
    combat.update(dt);
    updateBoats(dt, player);
    updateWagons(dt, player);   // ...and the cart, if you are in one
    updateGroundItems(dt);
    updateFalling(dt, LIT.diffuse.value);
    updateWork(dt, workCtx);
    updatePlates();           // ...and the name over each of your own
    updateHails(dt);          // ...and anybody you have stopped to talk to
    autosave(dt);             // ...and the world writes itself down
    tickSavedFlash(dt);       // ...and the button stops saying so
    updateNearBtn();          // ...and the button that commands them
    updateVillageLife(dt);
    updateFamily(dt);         // ...and your own household growing
    ensureChiefs(dt);
    updateMusters(dt);
    updatePeace(dt);
    sweepBells(dt);
    updateWar(dt);
    ensureFolk(dt);
    updateWorship(dt);
    updateLights(dt);
    updateChronicle(dt);
    updateFish(dt, player);
    growWorld();
  }
  blockEntities.tick(dt);
  updateBlockAnims(dt, { daylight });
  updateRising(dt);
  updateWater(dt);
  updatePower(dt);
  updateSky(dt);        // the clock itself: without this nobody ever gets tired
}

let realScale = 1;      // passes the last frame actually managed
let sunPush = 0;        // throttle on telling the server the fast-forward clock

// N — sleep the night away: the clock jumps to the NEXT local dawn, six in
// the morning where you stand. The same client-authoritative sun push the
// fast-forward key already makes, so a shared world's server takes the new
// time and everybody's sky agrees; pressed at noon it is an early night and
// a fresh start, which is what was asked for — a way to stop the dark.
function skipToDawn() {
  if (mode !== 'play' || !planet) return false;
  const cur = localHour(player.up) / 24;
  let ahead = 6 / 24 - cur;
  if (ahead <= 1e-4) ahead += 1;
  const jump = ahead * Math.PI * 2;
  sunAngle += jump;
  if (sunTarget !== null) sunTarget += jump;
  updateSky(0);
  net.sendSun?.(sunAngle);
  flash('the night passes — dawn, day ' + worldDay());
  return true;
}

function setTimeScale(n) {
  const was = timeScale;
  timeScale = TIME_SCALES.includes(n) ? n : 1;
  // stepping OFF the accelerator: tell the server where the day ended up,
  // once, so the shared clock lands on the same minute you did
  if (was > 1 && timeScale === 1) net.sendSun?.(sunAngle);
  const el = document.getElementById('speedBtn');
  if (el) el.textContent = timeScale === 1 ? 'speed (×1)' : `speed ×${timeScale}`;
  flash(timeScale === 1
    ? 'normal speed'
    : `×${timeScale} — the world hurries, you do not`);
}
document.getElementById('speedBtn')?.addEventListener('click', () => {
  setTimeScale(TIME_SCALES[(TIME_SCALES.indexOf(timeScale) + 1) % TIME_SCALES.length]);
});

// ---- the memory log ---------------------------------------------------------
//
// "The game freezes after a while" is the one bug that cannot be caught: it
// happens an hour into somebody's evening, the tab is dead by the time
// anybody could open a debugger, and nothing about it survives the reload.
// So the game writes down, every half minute, everything a freeze could be
// made of — the JS heap, the GPU's live geometries and textures, how many
// entities, chunks, block animations and scene objects there are, how big
// the edit diff has grown, and the worst frame since the last line — and
// posts it to the server, which appends it to memlog.txt next to the chief's
// log. A freeze is then a file that was being written up to the moment it
// happened, and the line before the gap says what was climbing.
const MEMLOG = { every: 30, spike: 250 };
let memClock = 5;             // the first line soon after the world opens
let memWorst = 0, memSpikes = 0;
function memLine() {
  const mem = performance.memory;
  const g = renderer.info.memory;
  const hour = mode === 'play' && player?.up ? localHour(player.up) : null;
  return [
    new Date().toISOString().slice(11, 19),
    `up ${Math.round(clock.elapsedTime)}s`,
    `day ${worldDay()}${hour == null ? '' : ` ${hour.toFixed(1)}h`}`,
    mode,
    mem ? `heap ${(mem.usedJSHeapSize / 1048576).toFixed(0)}/`
      + `${(mem.totalJSHeapSize / 1048576).toFixed(0)}MB` : 'heap ?',
    `geo ${g.geometries} tex ${g.textures}`,
    `chunks ${world?.chunkGroup?.children?.length ?? 0}`
      + ` q${world?.queue?.length ?? 0}`,
    `tris ${Math.round((world?.triangles ?? 0) / 1000)}k`,
    `ents ${entities.length}`,
    `anims ${blockAnimCount()}`,
    `scene ${scene.children.length}`,
    `edits ${edits.size}`,
    `drops ${groundItems?.length ?? 0}`,
    `worst ${Math.round(memWorst)}ms x${memSpikes}`,
    // the Realistic style's own load, when it is on: texels a block, the
    // layers on the card, and how many bodies wear a repaint
    ...(activeReal ? [`real ${realStatus().N}px ${realStatus().layers}L`
      + ` bodies ${realBodyCache()} q${realBodyQueue()}`] : []),
  ].join(' · ');
}
function memSample(rawDt) {
  const ms = rawDt * 1000;
  if (ms > memWorst) memWorst = ms;
  if (ms > MEMLOG.spike) memSpikes++;
  if ((memClock -= rawDt) > 0) return;
  memClock = MEMLOG.every;
  const line = memLine();
  memWorst = 0;
  memSpikes = 0;
  try {
    // keepalive, so a line sent as the tab dies still gets there
    fetch('/memlog', { method: 'POST', body: line, keepalive: true })
      .catch(() => {});
  } catch { /* no server: the log is the console's */ }
}
window.__memline = memLine;

// ---- what went wrong, written down --------------------------------------------
//
// The memory log says what was climbing; these lines say what broke. An
// uncaught error, a promise nobody caught, the graphics card taking the
// picture away — each goes into memlog.txt as a line of its own beside the
// numbers, a handful a minute at most, so the next "it stopped working" comes
// with its reason written next to it. The Mac window adds one more of its
// own: the page's process dying outright (see macwindow.swift).
let problemLines = 0, problemFrom = 0;
function logProblem(kind, text) {
  const now = performance.now();
  if (now - problemFrom > 60000) { problemFrom = now; problemLines = 0; }
  if (++problemLines > 6) return;
  const line = `${new Date().toISOString().slice(11, 19)} · ${kind} · `
    + `${String(text ?? '').replace(/\s+/g, ' ').slice(0, 600)}`;
  try {
    fetch('/memlog', { method: 'POST', body: line, keepalive: true }).catch(() => {});
  } catch { /* no server: the console has it */ }
}
window.addEventListener('error', (e) => logProblem('ERROR',
  `${e.message} @ ${String(e.filename ?? '').split('/').pop()}:${e.lineno}:${e.colno}`));
window.addEventListener('unhandledrejection', (e) => logProblem('REJECTED',
  e.reason?.stack ?? e.reason));
// The graphics card can take the context away — a driver reset, the GPU
// process restarting, memory — and three.js asks for it back. What it cannot
// put back by itself is the Realistic style's photographs, whose copies on
// this side are let go once they are on the card: those are built again.
renderer.domElement.addEventListener('webglcontextlost', () => {
  logProblem('CONTEXT LOST', `${currentStyle().id} · ${memLine()}`);
  flash('the graphics card dropped the picture — waiting for it back…');
});
renderer.domElement.addEventListener('webglcontextrestored', () => {
  logProblem('CONTEXT RESTORED', currentStyle().id);
  if (activeReal) applyRealism(currentStyle(), { rebuild: true });
  flash('the picture is back');
});
// A page the Mac window had to load again after the system ended it says so:
// the player is looking at a menu they did not ask for.
{
  const q = new URLSearchParams(location.search);
  if (q.has('recovered')) {
    flash('the game was stopped by the system (usually for memory) and has '
      + 'started again — worlds are as they were at their last save');
    q.delete('recovered');
    const rest = q.toString();
    history.replaceState(null, '', location.pathname + (rest ? `?${rest}` : '') + location.hash);
  }
}

// ONE BAD FRAME MUST NOT BE THE LAST ONE.
//
// three.js asks for the next frame AFTER this callback returns, so an
// exception anywhere in it — one entity with a NaN in it, one mesh the card
// would not take — meant the next frame was never asked for, and the game
// stood still for good with nothing on the screen to say why. That was "it
// stopped when I went quite far": an error, then a picture that never moved
// again, and in the Mac window not even the error's name, because an error
// thrown inside three.js (served from another site) reaches the page's error
// listener as "Script error." and nothing else.
//
// So the frame is three rooms with a door each: the world's turn, everything
// that follows it, and the drawing. A throw in one is caught, written into
// memlog.txt WITH its stack — a caught error keeps its details however
// foreign the code it came out of — and the others still run, so the picture
// keeps moving and the next report says where it broke.
const faults = new Map();          // message -> { n, first }
window.__faults = () => [...faults.entries()].map(([m, f]) => ({ m, ...f }));
function frameFault(room, err) {
  const msg = `${room} · ${err?.message ?? err}`;
  const f = faults.get(msg);
  if (f) { f.n++; return; }
  const stack = String(err?.stack ?? '').split('\n').slice(0, 6)
    .map((l) => l.trim()).join(' | ');
  faults.set(msg, { n: 1, first: new Date().toISOString(), stack });
  console.error(`frame fault in ${room}:`, err);
  logProblem('FRAME', `${msg} · ${stack}`);
  if (faults.size === 1) flash('something went wrong in the game — it has been written down, and the game is carrying on');
}

let lastDrawn = 0;
// how fast the game is actually running, over the frames frameLog holds — for
// a check of the cap, and for anybody wondering what the fan is doing
window.__frames = () => {
  const ms = [...frameLog].filter((x) => x > 0);
  const avg = ms.reduce((a, b) => a + b, 0) / Math.max(1, ms.length);
  return { fps: +(1000 / avg).toFixed(1), cap: video.fps, frames: ms.length };
};
renderer.setAnimationLoop((now) => {
  // The frame-rate cap (video.fps): at thirty, every other screen refresh is
  // let go without anything run or drawn, and the next one takes the whole
  // of the time since the last — the clock measures from the last frame it
  // saw, so nothing in the world runs slow. Four milliseconds of slack, or a
  // refresh that lands a hair early would be skipped and thirty become
  // twenty.
  if (video.fps < 60) {
    if (now - lastDrawn < 1000 / video.fps - 4) return;
    lastDrawn = now;
  }
  const rawDt = clock.getDelta();
  frameLog[frameAt++ % frameLog.length] = rawDt * 1000;
  memSample(rawDt);
  const dt = Math.min(rawDt, MAX_STEP);
  try { worldTurn(dt); } catch (err) { frameFault('world', err); }
  try { afterTurn(dt); } catch (err) { frameFault('after', err); }
  try { drawFrame(); } catch (err) { frameFault('draw', err); }
});

function worldTurn(dt) {
  if (travel.active) {
    // the flight owns the camera; running player physics would fight it
    travel.update(dt);
  } else if (mode === 'play') {
    keyLook(dt);
    edgeTurn(dt);
    updateLoo(dt);            // the seat before the legs, for the saddle's reason
    updateRiding(dt);         // reins before the legs: it eats the movement keys
    player.update(dt);
    updateFootsteps();
    updateTarget();
    updateMining(dt);
    updatePlacing(dt);
    updatePlannerPreview();   // the marked box follows the crosshair
    updateGhost();            // ...and so does an armed paste
    updateEntities(dt);
    syncRider();              // ...and the saddle after the horse has moved
    updateFarming(dt);
    combat.update(dt);
    updateBoats(dt, player);
    updateWagons(dt, player);   // ...and the cart, if you are in one
    updateGroundItems(dt);
    updateFalling(dt, LIT.diffuse.value);
    updateWork(dt, workCtx);  // woodcutters, farmhands, cooks, fetchers
    updatePlates();           // ...and the name over each of your own
    updateHails(dt);          // ...and anybody you have stopped to talk to
    autosave(dt);             // ...and the world writes itself down
    tickSavedFlash(dt);       // ...and the button stops saying so
    updateNearBtn();          // ...and the button that commands them
    updateVillageLife(dt);    // ...and the village filling its own beds
    updateFamily(dt);         // ...and your own household growing
    ensureChiefs(dt);         // every settlement has somebody in charge of it
    updateMusters(dt);        // ...and its chief, twice a day
    updatePeace(dt);          // ...and a wronged village cooling off
    sweepBells(dt);
    updateWar(dt);            // ...and one that has sent its men at another
    ensureFolk(dt);           // ...and somebody at home in the nearest of them
    updateWorship(dt);        // ...and the bell that empties the street
    updateLights(dt);         // ...and every lamp the dark will not come near
    updateChronicle(dt);      // ...and the day written down for every one
    updateFish(dt, player);
    if (meleeTimer > 0) meleeTimer -= dt;
    // where we are and what we hold, for everyone else. Actually transmitted
    // at the net's own tick, not per frame.
    const held = inventory.selectedId();
    net.setLocalState(
      player.pos, player.forward, player.pitch,
      held ? itemTile(held) : -1,
      held ? (isPlaceable(held) ? 1 : 2) : 0,
      (player.swingActive ? FLAG.SWINGING : 0) | (armed ? FLAG.ARMED : 0)
      | (player.inWater ? FLAG.IN_WATER : 0)
      | (player.grounded ? FLAG.GROUNDED : 0)
      | (player.flying ? FLAG.FLYING : 0));
  } else {
    controls.update();
  }
}

function afterTurn(dt) {
  // ...and then the world gets its extra time, before anything is drawn or
  // placed, so a frame shows where everybody actually ended up. The first
  // pass is the ordinary one above; these are the rest of the multiplier.
  if (timeScale > 1) {
    const t0 = performance.now();
    let i = 1;
    for (; i < timeScale; i++) {
      stepWorld(dt);
      if (performance.now() - t0 > STEP_BUDGET_MS) { i++; break; }
    }
    realScale = i;   // what the frame could actually afford
    // In a SHARED world the fast-forwarder is the clock, and everybody
    // follows. Two halves, and both matter:
    //
    //  * the server is told the new angle every second or so. Its set_sun
    //    only ever winds FORWARD, and the broadcast reaches every other
    //    player as an ordinary correction — a gap over half a radian snaps,
    //    so their day leaps ahead with yours rather than easing through a
    //    fake sunrise. What their world DID in the skipped hours arrives the
    //    way it always does: your machine simulated it, and every block it
    //    changed and every coin it moved ships as edits and ledger rows.
    //
    //  * incoming corrections are ignored while the multiplier is on. The
    //    server's clock runs at real time between pushes, so it is always a
    //    second behind the front of a x100 run — and easing toward it was
    //    the rubber-banding the player reported: forward, back, forward,
    //    back, for as long as the speed key was held.
    sunTarget = null;
    if ((sunPush -= dt) <= 0) { sunPush = 1.2; net.sendSun?.(sunAngle); }
  } else realScale = 1;
  updateSunShadow();     // ...and window.tick, or it works in one and not the other
  updateLampLight();
  // the Realistic style's repaints of the people and animals, a few
  // milliseconds a frame (see realbody.js) — and in window.tick
  if (activeReal) pumpRealBodies(3);
  if (Player.stuckReport && !stuckSaved) saveStuckReport();
  net.update(dt);        // transmits, interpolates; offline it does nothing
  remotes?.update(dt);   // poses every remote body
  // Aim the flat-horizon projection before anything is drawn or re-placed.
  // First person only: from orbit the whole point is to see a globe.
  // The drafting table is genuinely flat; bending it through the projection
  // that unrolls a globe would put curvature INTO the one world without any.
  flatten.setFlatten(flatHorizon && !CS.FLAT && mode === 'play'
    && !travel.active && viewIndex === 0);
  flatten.update(player.pos, R);
  placeLoose();
  blockEntities.tick(dt);              // O(active furnaces), usually zero
  updateBlockAnims(dt, { daylight });  // lids, furnace glow, flame, smoke
  updateSystemView(dt);
  updateWeather(dt, {
    pos: player.pos,
    playing: mode === 'play' && !travel.active,
    onSound: (n, o) => audio.play(n, o),
    daylight,
    // the storm clusters are world-anchored meshes, so with the flat horizon
    // on they have to be bent the same way the terrain is or a storm on the
    // horizon floats above a ground that has been unrolled out from under it
    bend: flatten.isFlat() ? (a, o) => flatten.flattenPoint(a, o) : null,
  });
  // ...and you only hear it where it is falling
  audio.setRain(worldRain * (activeWeather()?.wet ?? 0));
  // Outside updateEntities on purpose: the city has to be told when you are
  // NOT playing too, or a street's worth of buses would hang in the star
  // field the moment you went back to orbit.
  updateCityLife(dt, {
    pos: player.pos,
    playing: mode === 'play' && !travel.active,
    entities,
    onSound: (n, o) => audio.play(n, o),
  });
  updateSky(dt);
  // AFTER updateSky, which sets the open-air fog this overrides
  updateSubmerged(dt);
  // storm clouds are lit by a sky the deck itself has darkened, and by the
  // lightning: the same two terms updateSky puts on the ground
  updateClouds(dt, {
    daylight: cloudLight(),
    up: mode === 'play' ? player.pos : null,
    // how far the ground is drawn, so the unrolled sky covers it and no
    // further — sky.js has no other way to know. See its cull.
    maxDist: world?.viewDist,
  });
  audio.update(dt, { daylight });
  world?.update(camera, mode, mode === 'play' ? player.pos : null, CHUNK_MS);
  // ...ONCE A SECOND, not once a frame. growVillages surveys a plot for every
  // village still short of its day's house, and a village short of planks is
  // short of them for hours — so while any settlement on the planet waited
  // on its shelf, forty ground surveys ran sixty times a second. A house that
  // goes up a second late is not a house anybody saw go up late.
  if (mode === 'play' && (growClock -= dt) <= 0) { growClock = 1; growWorld(); }
  updateRising(dt);      // ...and the courses of the ones going up right now
  updateWater(dt);       // ...and whatever the last broken block let out
  updatePower(dt);       // ...and the current in whatever somebody wired up
  updateSleep(dt);       // the fade, and the night it skips at the bottom of it
  signs.sweep(dt);       // boards whose posts somebody else pulled up
  updateBins(dt);        // ...and whichever bin has had its day
  updatePlanHint();      // says what the planner is waiting for, if anything
  updateRoad(dt);        // ...and which ring you are on — see the realm
}

function drawFrame() {
  renderer.render(scene, camera);
  if (mode === 'play') {
    renderMinimap();
    updateClock();
    const p = player.pos;
    coordsEl.textContent =
      `X ${p.x.toFixed(0)}  Y ${p.y.toFixed(0)}  Z ${p.z.toFixed(0)}\n` +
      `alt ${((CS.FLAT ? p.y : p.length()) - R).toFixed(1)}`;
  }
}
